import java.util.*;
public class WordFrequency {public static void main(String[] args){String paragraph="Java is simple and Java is powerful. Java is popular";Map<String,Integer> map=new HashMap<>();for(String w:paragraph.toLowerCase().replaceAll("[^a-z ]"," ").split("\\s+"))if(!w.isBlank())map.put(w,map.getOrDefault(w,0)+1);List<Map.Entry<String,Integer>> list=new ArrayList<>(map.entrySet());list.sort((a,b)->b.getValue().compareTo(a.getValue()));for(var e:list)System.out.println(e.getKey()+": "+e.getValue());}}
